# Generated by Descant: acceptance tests.
# frozen_string_literal: true

require "rails_helper"

# The handoff routes read and replace every company's rows at once, so a
# company user's token, whatever its role, must never reach them.
RSpec.describe "Timekeeping internal handoff routes refuse company tokens" do
  include_context "timekeeping entry writes without transactional fixtures"

  let(:tenant_refusal_service_token) { "service-#{SecureRandom.hex(24)}" }

  around do |example|
    with_timekeeping_env(
      Timekeeping::Environment::TOKEN_PUBLIC_KEY => rsa_key_pair.public_key.to_pem,
      Timekeeping::Environment::SERVICE_TOKEN => tenant_refusal_service_token
    ) { example.run }
  end

  def tenant_refusal_table_counts
    %w[entries reservations invoice_operations audit_events idempotency_receipts outbox_snapshots].index_with do |table|
      ApplicationRecord.connection.select_value("SELECT COUNT(*) FROM #{table}").to_i
    end.merge("admission_generation" => Timekeeping::Admission.current.generation,
              "next_entry_id" => ApplicationRecord.connection.select_value(
                "SELECT CASE WHEN is_called THEN last_value + 1 ELSE last_value END FROM entries_id_seq"
              ).to_i)
  end

  # "Every handoff endpoint refuses a caller without service credentials"
  it "refuses owner and admin company tokens on every handoff route and leaves every company's rows unchanged" do
    empty_checkpoint = Timekeeping::Handoff::Checkpoint.build(
      tables: Timekeeping::Handoff::Checkpoint::TABLES.keys.index_with { [] }
    ).to_json
    routes = [
      [:get, "/internal/v1/handoff/checkpoint", nil],
      [:put, "/internal/v1/handoff/checkpoint", empty_checkpoint],
      [:post, "/internal/v1/handoff/entry_id_sequence", JSON.generate(above: 1_000_000)],
      [:get, "/internal/v1/handoff/outbox_position", nil],
      [:put, "/internal/v1/handoff/correction_snapshots", JSON.generate(generation: 2, version: 1, snapshots: [])],
      [:post, "/internal/v1/handoff/admission/fence", nil],
      [:post, "/internal/v1/handoff/admission/admit", JSON.generate(generation: 9)]
    ]
    before = tenant_refusal_table_counts

    %w[owner admin].each do |role|
      token = mint_token({ sub: 7, company_id: 1, role: })
      routes.each do |verb, path, body|
        headers = { "Authorization" => "Bearer #{token}", "Content-Type" => "application/json" }
        public_send(verb, path, params: body, headers:)

        expect([response.status, response.parsed_body]).to eq([401, { "reason" => "unauthorized" }]),
          "#{role} token reached #{verb.upcase} #{path}"
      end
    end

    expect(tenant_refusal_table_counts).to eq(before)
  end
end

RSpec.describe "Timekeeping internal handoff correction snapshots stay within one company" do
  include_context "timekeeping entry writes without transactional fixtures"

  let(:correction_scope_service_token) { "service-#{SecureRandom.hex(24)}" }

  around do |example|
    with_timekeeping_env(Timekeeping::Environment::SERVICE_TOKEN => correction_scope_service_token) { example.run }
  end

  def correction_scope_entry_fields(company_id, entry_id, locked:)
    at = Time.utc(2026, 3, 2, 9)
    {
      "id" => entry_id, "company_id" => company_id, "project_id" => 11, "user_id" => 21, "agent_id" => nil,
      "work_date" => "2026-03-02", "duration" => 60.0, "note" => "", "bill_status" => "unbilled",
      "review_status" => "not_required", "locked" => locked, "source" => "manual", "source_metadata" => {},
      "external_run_id" => nil, "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {},
      "discarded_at" => nil, "created_at" => at, "updated_at" => at
    }
  end

  # "Writing the same corrections again replaces them, so there is never a
  # second snapshot for one entry and generation."
  it "replaces only the corrected company's snapshot and leaves another company's snapshot with the same entry id and generation" do
    at = Time.utc(2026, 3, 2, 9)
    Entry.insert_all!([correction_scope_entry_fields(1, 301, locked: true).merge(
      "work_date" => Date.new(2026, 3, 2), "version" => 0, "created_at" => at, "updated_at" => at
    )])
    # Company 2 holds a snapshot for the same entry id at the same generation.
    OutboxSnapshot.insert_all!([correction_scope_entry_fields(2, 301, locked: true).merge(
      "work_date" => Date.new(2026, 3, 2), "version" => 4, "generation" => 2
    )])
    Timekeeping::Admission.fence!
    headers = { "Authorization" => "Bearer #{correction_scope_service_token}", "Content-Type" => "application/json" }
    body = JSON.generate(generation: 2, version: 1,
                         snapshots: [correction_scope_entry_fields(1, 301, locked: false)])

    2.times do
      put "/internal/v1/handoff/correction_snapshots", params: body, headers: headers
      expect(response.status).to eq(200)
    end

    rows = OutboxSnapshot.where(id: 301, generation: 2).order(:company_id)
                         .pluck(:company_id, :version, :locked)
    expect(rows).to eq([[1, 1, false], [2, 4, true]])
  end
end
